  1→//! Remote configuration fetching.
  2→//!
  3→//! This module provides functionality for fetching configuration files
  4→//! from remote URLs.
  5→
  6→use anyhow::{anyhow, Context, Result};
  7→use std::collections::HashMap;
  8→use std::path::PathBuf;
  9→use std::time::Duration;
 10→
 11→/// Fetches remote configuration files with caching.
 12→///
 13→/// # Example
 14→///
 15→/// ```no_run
 16→/// use bivvy::config::RemoteFetcher;
 17→/// use std::time::Duration;
 18→///
 19→/// let fetcher = RemoteFetcher::new(Duration::from_secs(30));
 20→///
 21→/// // Fetch a remote config file
 22→/// let content = fetcher.fetch("https://example.com/config.yml").unwrap();
 23→/// ```
 24→pub struct RemoteFetcher {
 25→    /// Request timeout.
 26→    timeout: Duration,
 27→    /// Cache directory for downloaded configs.
 28→    cache_dir: PathBuf,
 29→    /// HTTP client.
 30→    client: reqwest::blocking::Client,
 31→}
 32→
 33→impl RemoteFetcher {
 34→    /// Create a fetcher with the specified timeout.
 35→    pub fn new(timeout: Duration) -> Self {
 36→        let cache_dir = dirs::cache_dir()
 37→            .unwrap_or_else(|| PathBuf::from("~/.cache"))
 38→            .join("bivvy")
 39→            .join("remote-configs");
 40→
 41→        Self {
 42→            timeout,
 43→            cache_dir,
 44→            client: reqwest::blocking::Client::builder()
 45→                .timeout(timeout)
 46→                .build()
 47→                .expect("Failed to create HTTP client"),
 48→        }
 49→    }
 50→
 51→    /// Create a fetcher with a custom cache directory.
 52→    pub fn with_cache_dir(timeout: Duration, cache_dir: PathBuf) -> Self {
 53→        Self {
 54→            timeout,
 55→            cache_dir,
 56→            client: reqwest::blocking::Client::builder()
 57→                .timeout(timeout)
 58→                .build()
 59→                .expect("Failed to create HTTP client"),
 60→        }
 61→    }
 62→
 63→    /// Fetch a configuration file from a URL.
 64→    pub fn fetch(&self, url: &str) -> Result<String> {
 65→        // Check cache first
 66→        if let Some(cached) = self.check_cache(url)? {
 67→            return Ok(cached);
 68→        }
 69→
 70→        // Fetch from remote
 71→        let content = self.fetch_remote(url)?;
 72→
 73→        // Cache the result
 74→        self.save_cache(url, &content)?;
 75→
 76→        Ok(content)
 77→    }
 78→
 79→    /// Fetch a configuration file, bypassing cache.
 80→    pub fn fetch_fresh(&self, url: &str) -> Result<String> {
 81→        self.fetch_remote(url)
 82→    }
 83→
 84→    /// Fetch with authentication header.
 85→    pub fn fetch_with_auth(&self, url: &str, auth: &AuthHeader) -> Result<String> {
 86→        let response = self
 87→            .client
 88→            .get(url)
 89→            .header(&auth.header_name, &auth.header_value)
 90→            .send()
 91→            .with_context(|| format!("Failed to fetch {}", url))?;
 92→
 93→        if !response.status().is_success() {
 94→            return Err(anyhow!("HTTP {} fetching {}", response.status(), url));
 95→        }
 96→
 97→        response
 98→            .text()
 99→            .with_context(|| format!("Failed to read response from {}", url))
100→    }

  1→//! Config command implementation.
  2→//!
  3→//! The `bivvy config` command shows resolved configuration.
  4→
  5→use std::path::{Path, PathBuf};
  6→
  7→use crate::cli::args::ConfigArgs;
  8→use crate::config::{load_merged_config, ConfigPaths};
  9→use crate::error::{BivvyError, Result};
 10→use crate::ui::{OutputMode, UserInterface};
 11→
 12→use super::dispatcher::{Command, CommandResult};
 13→
 14→/// The config command implementation.
 15→pub struct ConfigCommand {
 16→    project_root: PathBuf,
 17→    args: ConfigArgs,
 18→}
 19→
 20→impl ConfigCommand {
 21→    /// Create a new config command.
 22→    pub fn new(project_root: &Path, args: ConfigArgs) -> Self {
 23→        Self {
 24→            project_root: project_root.to_path_buf(),
 25→            args,
 26→        }
 27→    }
 28→
 29→    /// Get the project root path.
 30→    pub fn project_root(&self) -> &Path {
 31→        &self.project_root
 32→    }
 33→
 34→    /// Get the command arguments.
 35→    pub fn args(&self) -> &ConfigArgs {
 36→        &self.args
 37→    }
 38→}
 39→
 40→impl Command for ConfigCommand {
 41→    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
 42→        // Load configuration
 43→        let config = match load_merged_config(&self.project_root) {
 44→            Ok(c) => c,
 45→            Err(BivvyError::ConfigNotFound { .. }) => {
 46→                ui.error("No configuration found. Run 'bivvy init' first.");
 47→                return Ok(CommandResult::failure(2));
 48→            }
 49→            Err(e) => return Err(e),
 50→        };
 51→
 52→        // Apply config default_output when no CLI flag was explicitly set
 53→        if ui.output_mode() == OutputMode::Normal {
 54→            ui.set_output_mode(config.settings.default_output.into());
 55→        }
 56→
 57→        // Show config file path(s)
 58→        let paths = ConfigPaths::discover(&self.project_root);
 59→        let existing: Vec<_> = paths.all_existing();
 60→        if !existing.is_empty() {
 61→            for path in &existing {
 62→                ui.message(&format!("# {}", path.display()));
 63→            }
 64→            ui.message("");
 65→        }
 66→
 67→        // Output format
 68→        if self.args.json {
 69→            let json =
 70→                serde_json::to_string_pretty(&config).map_err(|e| BivvyError::Other(e.into()))?;
 71→            ui.message(&json);
 72→        } else {
 73→            let yaml = serde_yaml::to_string(&config).map_err(|e| BivvyError::Other(e.into()))?;
 74→            ui.message(&yaml);
 75→        }
 76→
 77→        Ok(CommandResult::success())
 78→    }
 79→}
