    #[test]
    fn environment_override_empty_string_is_not_null() {
        let yaml = r#"command: """#;
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(o.command, Some("".to_string()));
    }

    // --- Unknown field rejection tests ---

    #[test]
    fn rejects_unknown_top_level_field() {
        let yaml = r#"
app_name: MyApp
unknown_field: oops
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown top-level field must be rejected");
        let msg = result.unwrap_err().to_string();
        assert!(
            msg.contains("unknown_field"),
            "error should name the unknown field, got: {msg}"
        );
    }

    #[test]
    fn rejects_typo_in_top_level_field() {
        let yaml = r#"
ap_name: MyApp
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "typo in top-level field must be rejected");
    }

    #[test]
    fn rejects_unknown_settings_field() {
        let yaml = r#"
settings:
  default_output: quiet
  unknown_setting: true
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown settings field must be rejected");
    }

    #[test]
    fn rejects_unknown_step_field() {
        let yaml = r#"
steps:
  test:
    command: "echo test"
    comand: "echo typo"
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown step field must be rejected");
    }

    #[test]
    fn rejects_unknown_workflow_field() {
        let yaml = r#"
workflows:
  default:
    steps: [test]
    stpes: [test]
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown workflow field must be rejected");
    }

    #[test]
    fn rejects_unknown_step_override_field() {
        let yaml = r#"
            skip_prompt: true
            unknown: true
        "#;
        let result: Result<StepOverride, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "unknown step override field must be rejected"
        );
    }

    #[test]
    fn rejects_unknown_workflow_settings_field() {
        let yaml = r#"
            non_interactive: true
            bogus: false
        "#;
        let result: Result<WorkflowSettings, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "unknown workflow settings field must be rejected"
        );
    }

    #[test]
    fn rejects_unknown_environment_config_field() {
        let yaml = r#"
            default_workflow: ci
            extra: nope
        "#;
        let result: Result<EnvironmentConfig, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "unknown environment config field must be rejected"
        );
    }

    #[test]
    fn rejects_unknown_step_environment_override_field() {
        let yaml = r#"
            command: "echo ci"
            bogus_field: true
        "#;
        let result: Result<StepEnvironmentOverride, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "unknown step environment override field must be rejected"
        );
    }

    #[test]
    fn valid_config_still_parses_after_strict_mode() {
        let yaml = r#"
app_name: "MyApp"
settings:
  default_output: quiet
  logging: true
  parallel: true
  max_parallel: 8
steps:
  deps:
    command: "yarn install"
    depends_on: [other]
    watches: [package.json]
  other:
    command: "echo other"
workflows:
  default:
    description: "Full setup"
    steps: [other, deps]
    overrides:
      deps:
        skip_prompt: true
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(config.app_name, Some("MyApp".to_string()));
        assert_eq!(config.settings.default_output, OutputMode::Quiet);
        assert!(config.steps.contains_key("deps"));
        assert!(config.workflows.contains_key("default"));
    }
}

