        let config: EnvironmentConfig = serde_yaml::from_str("").unwrap();
        assert!(config.detect.is_empty());
        assert!(config.default_workflow.is_none());
        assert!(config.provided_requirements.is_empty());
    }

    #[test]
    fn parses_nested_composite_checks() {
        let yaml = r#"
steps:
  complex:
    command: "echo complex"
    completed_check:
      type: all
      checks:
        - type: file_exists
          path: "required.txt"
        - type: any
          checks:
            - type: file_exists
              path: "option_a.txt"
            - type: file_exists
              path: "option_b.txt"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let check = config.steps["complex"].completed_check.as_ref().unwrap();
        if let CompletedCheck::All { checks } = check {
            assert_eq!(checks.len(), 2);
            assert!(matches!(&checks[1], CompletedCheck::Any { .. }));
        } else {
            panic!("Expected All check");
        }
    }

    // --- 7A: Schema override parsing tests ---

    #[test]
    fn environment_override_depends_on_parses() {
        let yaml = r#"
            depends_on: [a, b]
        "#;
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(o.depends_on, Some(vec!["a".to_string(), "b".to_string()]));
    }

    #[test]
    fn environment_override_watches_parses() {
        let yaml = r#"
            watches: []
        "#;
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(o.watches, Some(vec![]));
    }

    #[test]
    fn environment_override_title_parses() {
        let yaml = r#"
            title: "CI Title"
        "#;
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(o.title, Some("CI Title".to_string()));
    }

    // --- Vars parsing tests ---

    #[test]
    fn parses_static_var() {
        let yaml = r#"
vars:
  name: "bivvy"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(matches!(
            config.vars.get("name"),
            Some(VarDefinition::Static(v)) if v == "bivvy"
        ));
    }

    #[test]
    fn parses_computed_var() {
        let yaml = r#"
vars:
  v:
    command: "echo 1"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(matches!(
            config.vars.get("v"),
            Some(VarDefinition::Computed { command }) if command == "echo 1"
        ));
    }

    #[test]
    fn parses_mixed_vars() {
        let yaml = r#"
vars:
  app_name: "bivvy"
  version:
    command: "echo 1.0.0"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(config.vars.len(), 2);
        assert!(matches!(
            config.vars.get("app_name"),
            Some(VarDefinition::Static(_))
        ));
        assert!(matches!(
            config.vars.get("version"),
            Some(VarDefinition::Computed { .. })
        ));
    }

    #[test]
    fn empty_vars_defaults() {
        let config: BivvyConfig = serde_yaml::from_str("").unwrap();
        assert!(config.vars.is_empty());
    }

    #[test]
    fn serialize_omits_empty_vars() {
        let config: BivvyConfig = serde_yaml::from_str("app_name: test").unwrap();
        let yaml = serde_yaml::to_string(&config).unwrap();
        assert!(!yaml.contains("vars"), "empty vars should be omitted");
    }

    // --- Precondition parsing tests ---

    #[test]
    fn parses_precondition_command_succeeds() {
        let yaml = r#"
steps:
  release:
    command: "git tag v1"
    precondition:
      type: command_succeeds
      command: "test $(git branch --show-current) = main"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["release"];
        assert!(matches!(
            step.precondition,
            Some(CompletedCheck::CommandSucceeds { .. })
        ));
    }

    #[test]
    fn parses_precondition_all() {
        let yaml = r#"
steps:
  release:
    command: "git tag v1"
    precondition:
      type: all
      checks:
        - type: command_succeeds
          command: "test $(git branch --show-current) = main"
        - type: command_succeeds
          command: "git diff --quiet"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["release"];
        if let Some(CompletedCheck::All { checks }) = &step.precondition {
            assert_eq!(checks.len(), 2);
        } else {
            panic!("Expected All precondition");
        }
    }

    #[test]
    fn precondition_defaults_none() {
        let yaml = r#"
            command: "echo hello"
        "#;
        let config: StepConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(config.precondition.is_none());
    }

    #[test]
    fn serialize_omits_none_precondition() {
        let config: BivvyConfig = serde_yaml::from_str(
            r#"
steps:
  hello:
    command: "echo hello"
"#,
        )
        .unwrap();
        let yaml = serde_yaml::to_string(&config).unwrap();
        assert!(
            !yaml.contains("precondition"),
            "None precondition should be omitted"
        );
    }

    #[test]
    fn environment_override_bare_null_parses_as_none() {
        let yaml = "command:";
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert!(o.command.is_none());
    }

    #[test]
    fn environment_override_empty_string_is_not_null() {
        let yaml = r#"command: """#;
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(o.command, Some("".to_string()));
    }

    // --- Unknown field rejection tests ---

    #[test]
    fn rejects_unknown_top_level_field() {
        let yaml = r#"
app_name: MyApp
unknown_field: oops
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown top-level field must be rejected");
        let msg = result.unwrap_err().to_string();
        assert!(
            msg.contains("unknown_field"),
            "error should name the unknown field, got: {msg}"
        );
    }

    #[test]
    fn rejects_typo_in_top_level_field() {
        let yaml = r#"
ap_name: MyApp
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "typo in top-level field must be rejected");
    }

    #[test]
    fn rejects_unknown_settings_field() {
        let yaml = r#"
settings:
  default_output: quiet
  unknown_setting: true
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown settings field must be rejected");
    }

    #[test]
    fn rejects_unknown_step_field() {
        let yaml = r#"
steps:
  test:
    command: "echo test"
    comand: "echo typo"
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown step field must be rejected");
    }

    #[test]
    fn rejects_unknown_workflow_field() {
        let yaml = r#"
workflows:
  default:
    steps: [test]
    stpes: [test]
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown workflow field must be rejected");
    }

    #[test]
    fn rejects_unknown_step_override_field() {
        let yaml = r#"
            skip_prompt: true
            unknown: true
        "#;
        let result: Result<StepOverride, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "unknown step override field must be rejected"
        );
    }

    #[test]
    fn rejects_unknown_workflow_settings_field() {
        let yaml = r#"
            non_interactive: true
            bogus: false
        "#;
        let result: Result<WorkflowSettings, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "unknown workflow settings field must be rejected"
        );
    }

    #[test]
    fn rejects_unknown_environment_config_field() {
        let yaml = r#"
            default_workflow: ci
            extra: nope
        "#;
        let result: Result<EnvironmentConfig, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "unknown environment config field must be rejected"
        );
    }

    #[test]
    fn rejects_unknown_step_environment_override_field() {
        let yaml = r#"
            command: "echo ci"
            bogus_field: true
        "#;
        let result: Result<StepEnvironmentOverride, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "unknown step environment override field must be rejected"
        );
    }

    #[test]
    fn valid_config_still_parses_after_strict_mode() {
        let yaml = r#"
app_name: "MyApp"
settings:
  default_output: quiet
  logging: true
  parallel: true
  max_parallel: 8
steps:
  deps:
    command: "yarn install"
    depends_on: [other]
    watches: [package.json]
  other:
    command: "echo other"
workflows:
  default:
    description: "Full setup"
    steps: [other, deps]
    overrides:
      deps:
        skip_prompt: true
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(config.app_name, Some("MyApp".to_string()));
        assert_eq!(config.settings.default_output, OutputMode::Quiet);
        assert!(config.steps.contains_key("deps"));
        assert!(config.workflows.contains_key("default"));
    }
}

